import os
import sys
import json
import queue
import threading
from typing import Iterator, Optional

import sounddevice as sd
from google.cloud import speech


class StreamingSpeechToText:
    def __init__(
        self,
        sample_rate: int = 16000,
        block_size: int = 8000,
        language_code: str = "en-US",
        interim_results: bool = True,
    ):
        self.sample_rate = sample_rate
        self.block_size = block_size
        self.language_code = language_code
        self.interim_results = interim_results
        self._audio_queue: "queue.Queue[Optional[bytes]]" = queue.Queue()
        self._stop_event = threading.Event()
        self._client = speech.SpeechClient()

    def _audio_callback(self, indata, frames, time, status):
        if status:
            pass
        self._audio_queue.put(bytes(indata))

    def _request_generator(self) -> Iterator[speech.StreamingRecognizeRequest]:
        while not self._stop_event.is_set():
            chunk = self._audio_queue.get()
            if chunk is None:
                return
            yield speech.StreamingRecognizeRequest(audio_content=chunk)

    def _build_streaming_config(self) -> speech.StreamingRecognitionConfig:
        recognition_config = speech.RecognitionConfig(
            encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
            sample_rate_hertz=self.sample_rate,
            language_code=self.language_code,
            enable_automatic_punctuation=True,
            model="latest_long",
        )
        return speech.StreamingRecognitionConfig(
            config=recognition_config,
            interim_results=self.interim_results,
            single_utterance=False,
        )

    def transcribe(self) -> Iterator[str]:
        streaming_config = self._build_streaming_config()
        requests = self._request_generator()
        try:
            with sd.RawInputStream(
                samplerate=self.sample_rate,
                blocksize=self.block_size,
                dtype="int16",
                channels=1,
                callback=self._audio_callback,
            ):
                responses = self._client.streaming_recognize(
                    config=streaming_config,
                    requests=requests,
                )
                for response in responses:
                    if self._stop_event.is_set():
                        break
                    for result in response.results:
                        if result.alternatives:
                            transcript = result.alternatives[0].transcript.strip()
                            if transcript:
                                yield transcript
        finally:
            self.stop()

    def stop(self):
        if not self._stop_event.is_set():
            self._stop_event.set()
            self._audio_queue.put(None)


def stream_microphone_interim_transcripts(
    sample_rate: int = 16000,
    block_size: int = 8000,
    language_code: str = "en-US",
) -> Iterator[str]:
    stt = StreamingSpeechToText(
        sample_rate=sample_rate,
        block_size=block_size,
        language_code=language_code,
    )
    yield from stt.transcribe()


if __name__ == "__main__":
    try:
        for transcript in stream_microphone_interim_transcripts():
            print(transcript, flush=True)
    except KeyboardInterrupt:
        sys.exit(0)
